66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
74	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
75	     * and a dotted domain (e.g. {@code not-an-email}).
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
78	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
79	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
80	
81	    /**
82	     * Disposable email domains that are not allowed for an owner. An email whose domain (the part
83	     * after the '@', compared case-insensitively) is listed here is rejected with 400 Bad Request.
84	     */
85	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
86	        "mailinator.com",
87	        "tempmail.com",
88	        "guerrillamail.com");
89	
90	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
91	    private static final String DEFAULT_COUNTRY_CODE = "61";
92	
93	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
94	    private static final int MAX_OWNERS_PER_CITY = 50;
95	
96	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
97	    private static final int MAX_OWNERS_PER_DAY = 100;
98	
99	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
100	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
101	
102	    /** Fixed public-holiday calendar: a registration date landing on any of these is rolled forward past it. */
103	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
104	        LocalDate.of(2026, 1, 1),
105	        LocalDate.of(2026, 1, 26),
106	        LocalDate.of(2026, 4, 25),
107	        LocalDate.of(2026, 12, 25),
108	        LocalDate.of(2026, 12, 28));
109	
110	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
111	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
112	
113	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
114	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
115	
116	    /**
117	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
118	     * is listed here must carry exactly the required number of national digits, otherwise it is
119	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
120	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
121	     */
122	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
123	        "61", 9,
124	        "1", 10);
125	
126	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
127	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
128	        "ST", "STREET",
129	        "RD", "ROAD",
130	        "AVE", "AVENUE");
131	
132	    /** A well-formed postcode: exactly four digits. */
133	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
134	
135	    /** City to canonical region for the fixed city-to-region table (cities not listed have no region). */
136	    private static final Map<String, String> CITY_REGION = Map.of(
137	        "Sydney", "NSW",
138	        "Melbourne", "VIC",
139	        "Brisbane", "QLD");
140	
141	    /** Region to its inclusive 4-digit postcode range {low, high}. */
142	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
143	        "NSW", new int[] {2000, 2099},
144	        "VIC", new int[] {3000, 3099},
145	        "QLD", new int[] {4000, 4099});
146	
147	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
148	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
149	
150	    private final ClinicService clinicService;
151	
152	    private final OwnerMapper ownerMapper;
153	
154	    private final PetMapper petMapper;
155	
156	    private final VisitMapper visitMapper;
157	
158	    public OwnerRestControllerV1(ClinicService clinicService,
159	                                 OwnerMapper ownerMapper,
160	                                 PetMapper petMapper,
161	                                 VisitMapper visitMapper) {
162	        this.clinicService = clinicService;
163	        this.ownerMapper = ownerMapper;
164	        this.petMapper = petMapper;
165	        this.visitMapper = visitMapper;
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
171	        Collection<Owner> owners;
172	        if (lastName != null) {
173	            owners = this.clinicService.findOwnerByLastName(lastName);
174	        } else {
175	            owners = this.clinicService.findAllOwners();
176	        }
177	        if (owners.isEmpty()) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        owners.forEach(this::populateHouseholdSize);
181	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        populateHouseholdSize(owner);
192	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
198	        List<String> missingFields = new ArrayList<>();
199	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
200	            missingFields.add("firstName");
201	        }
202	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
203	            missingFields.add("lastName");
204	        }
205	        // Normalize each supplied address form up front. The structured fields are preferred when
206	        // present; the flat 'address' input remains accepted for backward compatibility. An owner is
207	        // valid when it supplies an address in EITHER form (a non-blank addressLine1, or the flat
208	        // address). A whitespace-only value collapses to the empty string and counts as absent.
209	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
210	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
211	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
212	        boolean hasStructuredAddress = StringUtils.hasText(normalizedAddressLine1);
213	        boolean hasFlatAddress = StringUtils.hasText(normalizedFlatAddress);
214	        if (!hasStructuredAddress && !hasFlatAddress) {
215	            missingFields.add("address");
216	        }
217	        // Compose the stored/returned address: the structured lines when present (addressLine1, with a
218	        // single space and addressLine2 appended when addressLine2 is present), otherwise the flat form.
219	        String composedAddress;
220	        if (hasStructuredAddress) {
221	            composedAddress = StringUtils.hasText(normalizedAddressLine2)
222	                ? normalizedAddressLine1 + " " + normalizedAddressLine2
223	                : normalizedAddressLine1;
224	        } else {
225	            composedAddress = normalizedFlatAddress;
226	        }
227	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
228	            missingFields.add("city");
229	        }
230	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
231	            missingFields.add("telephone");
232	        }
233	        if (!missingFields.isEmpty()) {
234	            throw new InvalidRequestException(missingFields);
235	        }
236	        HttpHeaders headers = new HttpHeaders();
237	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
238	        // A newly created owner is never soft-deleted.
239	        owner.setDeleted(false);
240	        // Store (and later return) the normalized structured lines and the composed address. The
241	        // structured lines are kept only when the structured form was supplied; otherwise they are
242	        // cleared so the response reflects the flat form that was actually used.
243	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
244	        owner.setAddressLine2(hasStructuredAddress && StringUtils.hasText(normalizedAddressLine2)
245	            ? normalizedAddressLine2 : null);
246	        owner.setAddress(composedAddress);
247	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
248	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
249	        owner.setTelephone(normalizedTelephone);
250	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
251	        owner.setEmail(normalizeEmail(owner.getEmail()));
252	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
253	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
254	        validatePostcode(owner.getCity(), owner.getPostcode());
255	        // Reject a supplied registration date that lies in the future (later than the server's current
256	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
257	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
258	            throw new InvalidRequestException(List.of("registrationDate"));
259	        }
260	        // Default the (optional) registration date to the server's current date when none was supplied.
261	        if (owner.getRegistrationDate() == null) {
262	            owner.setRegistrationDate(LocalDate.now());
263	        }
264	        // The effective registration date must fall on a business day: when it lands on a Saturday,
265	        // Sunday or a listed public holiday (whether supplied or defaulted above), roll it forward to
266	        // the next non-holiday business day. Every value derived from the registration date below
267	        // (daily create-limit, membership number) uses this adjusted date.
268	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
269	        // Reject the request once the maximum number of owners for the owner's registration day has
270	        // been reached (100 or more owners already created on that date).
271	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
272	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
273	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
274	        }
275	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
276	        // owner's registration day at the moment this owner was created; otherwise clear it.
277	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
278	        // Reject the request when the owner's city has already reached its owner capacity.
279	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
280	            throw new CityCapacityException(owner.getCity());
281	        }
282	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
283	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
284	        // so any two owners with the same last name and postcode automatically resolve to the same
285	        // household without an explicit opt-in. It is assigned up front so it feeds duplicate
286	        // detection (the identity key below), the household-size read-back and household-duplicate
287	        // detection alike.
288	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
289	        owner.setHouseholdId(householdId);
290	        // Household-duplicate detection: because the household is keyed on (lastName, postcode), any
291	        // existing owner already carrying this householdId is a member of the same household, so this
292	        // create is a household duplicate. Reject it with 409 unless the caller opts in via
293	        // 'sharesHousehold', which now only bypasses this block (the household link already exists by
294	        // construction) and marks the owner as a declared household member.
295	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
296	            .filter(existing -> !existing.isDeleted())
297	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
298	        boolean declaredHouseholdMember = false;
299	        if (householdMemberExists) {
300	            if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
301	                declaredHouseholdMember = true;
302	            } else {
303	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getPostcode());
304	            }
305	        }
306	        // All duplicate detection is consolidated into this single derived identity key
307	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
308	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
309	        // telephone is part of the key, two members of the same household with different telephones
310	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
311	        String identityKey = owner.getIdentityKey();
312	        boolean identityCollision = this.clinicService.findAllOwners().stream()
313	            .filter(existing -> !existing.isDeleted())
314	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
315	        if (identityCollision) {
316	            throw new DuplicateIdentityException(identityKey);
317	        }
318	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
319	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
320	        // this owner's last name (compared case-insensitively with collapsed whitespace) and
321	        // postcode while carrying a DIFFERENT normalized telephone. When several existing owners
322	        // match, the one with the lowest id is chosen so the result is deterministic. A declared
323	        // household member is an intentional co-resident, not a suspected duplicate, so it is never
324	        // flagged (a create that reaches this point sharing a last name and postcode with an
325	        // existing owner is precisely a declared household member).
326	        Owner softMatch = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
327	        if (softMatch != null) {
328	            owner.setPossibleDuplicate(true);
329	            owner.setPossibleDuplicateOf(softMatch.getId());
330	        } else {
331	            owner.setPossibleDuplicate(false);
332	        }
333	        // Record how many existing owners already share this first name and last name
334	        // (compared case-insensitively) before this owner is created.
335	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
336	        // Assign the customer code '<REGION>-<HASH8>' before persisting.
337	        owner.setCustomerCode(generateCustomerCode(owner));
338	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
339	        // digits of the fiscal year the registration date falls in (e.g. 'NSW-1A2B3C4D-M27').
340	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
341	        this.clinicService.saveOwner(owner);
342	        populateHouseholdSize(owner);
343	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
344	        // Emit an audit line carrying the new owner's id, customer code, registration date,
345	        // numeric membership level and membership number.
346	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
347	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
348	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
349	        headers.setLocation(UriComponentsBuilder.newInstance()
350	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
351	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
352	    }
353	
354	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
355	    @Override
356	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
357	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
358	        if (currentOwner == null) {
359	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
360	        }
361	        currentOwner.setAddress(ownerFieldsDto.getAddress());
362	        currentOwner.setCity(ownerFieldsDto.getCity());
363	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
364	        currentOwner.setLastName(ownerFieldsDto.getLastName());
365	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
366	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
367	        this.clinicService.saveOwner(currentOwner);
368	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
369	    }
370	
371	    /**
372	     * Populate the owner's household size: the number of owners sharing this owner's
373	     * {@code householdId} (including the owner itself). An owner with no household is a household
374	     * of one.
375	     *
376	     * @param owner the owner whose household size should be computed and set
377	     */
378	    private void populateHouseholdSize(Owner owner) {
379	        String householdId = owner.getHouseholdId();
380	        if (!StringUtils.hasText(householdId)) {
381	            owner.setHouseholdSize(1);
382	            return;
383	        }
384	        int size = (int) this.clinicService.findAllOwners().stream()
385	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
386	            .count();
387	        owner.setHouseholdSize(size);
388	    }
389	
390	    /**
391	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
392	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
393	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
394	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
395	     * longer any per-city sequence number.
396	     *
397	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
398	     * @return the generated (collision-free) customer code
399	     */
400	    private String generateCustomerCode(Owner owner) {
401	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
402	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
403	        String baseCode = region + "-" + hash8;
404	        return deduplicateCustomerCode(baseCode);
405	    }
406	
407	    /**
408	     * Return a customer code that does not collide with any existing owner's customer code. When the
409	     * given base code is already unique it is returned unchanged; otherwise {@code -<n>} is appended
410	     * with the smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW-1A2B3C4D},
411	     * then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, ...). The incoming owner is not yet
412	     * persisted, so it never counts as a collision with itself.
413	     *
414	     * @param baseCode the computed {@code <REGION>-<HASH8>} customer code
415	     * @return the de-duplicated customer code
416	     */
417	    private String deduplicateCustomerCode(String baseCode) {
418	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
419	            .map(Owner::getCustomerCode)
420	            .filter(java.util.Objects::nonNull)
421	            .collect(java.util.stream.Collectors.toSet());
422	        if (!existingCodes.contains(baseCode)) {
423	            return baseCode;
424	        }
425	        int n = 2;
426	        String candidate = baseCode + "-" + n;
427	        while (existingCodes.contains(candidate)) {
428	            n++;
429	            candidate = baseCode + "-" + n;
430	        }
431	        return candidate;
432	    }
433	
434	    /**
435	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
436	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
437	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
438	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
439	     * known region.
440	     *
441	     * @param postcode the owner's postcode, may be {@code null}
442	     * @param city     the owner's city
443	     * @return the derived region code
444	     */
445	    private String deriveRegion(String postcode, String city) {
446	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
447	            int value = Integer.parseInt(postcode);
448	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
449	                int[] range = entry.getValue();
450	                if (value >= range[0] && value <= range[1]) {
451	                    return entry.getKey();
452	                }
453	            }
454	        }
455	        String region = CITY_REGION.get(city);
456	        return region != null ? region : "UNKNOWN";
457	    }
458	
459	    /**
460	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
461	     * bytes of {@code input}.
462	     *
463	     * @param input  the value to digest
464	     * @param length the number of leading hex characters to return
465	     * @return the truncated upper-case hex digest
466	     */
467	    private String shortSha256Hex(String input, int length) {
468	        try {
469	            byte[] digest = MessageDigest.getInstance("SHA-256")
470	                .digest(input.getBytes(StandardCharsets.UTF_8));
471	            StringBuilder sb = new StringBuilder(digest.length * 2);
472	            for (byte b : digest) {
473	                sb.append(String.format("%02x", b));
474	            }
475	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
476	        } catch (java.security.NoSuchAlgorithmException e) {
477	            throw new IllegalStateException("SHA-256 not available", e);
478	        }
479	    }
480	
481	    /**
482	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
483	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
484	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
485	     * date that is stored, returned and used for every value derived from it.
486	     *
487	     * @param date the effective registration date (supplied or defaulted)
488	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
489	     */
490	    private LocalDate rollToBusinessDay(LocalDate date) {
491	        while (!isBusinessDay(date)) {
492	            date = date.plusDays(1);
493	        }
494	        return date;
495	    }
496	
497	    /**
498	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
499	     *
500	     * @param date the date to test
501	     * @return {@code true} when the date is a non-holiday weekday
502	     */
503	    private boolean isBusinessDay(LocalDate date) {
504	        DayOfWeek dayOfWeek = date.getDayOfWeek();
505	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
506	            return false;
507	        }
508	        return !PUBLIC_HOLIDAYS.contains(date);
509	    }
510	
511	    /**
512	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
513	     * last two digits of the fiscal year that the (business-day-adjusted) {@code registrationDate}
514	     * falls in (e.g. {@code SYD-SMI-0007-M27} for a registration in FY27).
515	     *
516	     * @param customerCode     the owner's already-assigned customer code
517	     * @param registrationDate the owner's business-day-adjusted registration date
518	     * @return the generated membership number
519	     */
520	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
521	        String yy = String.format("%02d", fiscalYear(registrationDate) % 100);
522	        return String.format("%s-M%s", customerCode, yy);
523	    }
524	
525	    /**
526	     * The fiscal year that the given date falls in. The fiscal year starts on 1 July, so a date in
527	     * July to December belongs to the fiscal year ending in the following calendar year, and a date
528	     * in January to June belongs to the fiscal year ending in the same calendar year. The fiscal
529	     * year is identified by that ending calendar year (e.g. 1 July 2026 to 30 June 2027 is 2027).
530	     *
531	     * @param date the date whose fiscal year is required
532	     * @return the fiscal year's ending calendar year
533	     */
534	    private int fiscalYear(LocalDate date) {
535	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
536	    }
537	
538	    /**
539	     * Count the existing owners that share the given first name and last name, comparing each
540	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
541	     * yet persisted, so it is not included in the count.
542	     *
543	     * @param firstName the incoming owner's first name
544	     * @param lastName  the incoming owner's last name
545	     * @return the number of existing namesakes
546	     */
547	    private int countNamesakes(String firstName, String lastName) {
548	        String normalizedFirstName = normalizeForComparison(firstName);
549	        String normalizedLastName = normalizeForComparison(lastName);
550	        return (int) this.clinicService.findAllOwners().stream()
551	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
552	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
553	            .count();
554	    }
555	
556	    /**
557	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
558	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
559	     *
560	     * @param city the incoming owner's city
561	     * @return the number of existing owners already in that city
562	     */
563	    private int countOwnersInCity(String city) {
564	        String normalizedCity = normalizeForComparison(city);
565	        return (int) this.clinicService.findAllOwners().stream()
566	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
567	            .count();
568	    }
569	
570	    /**
571	     * Count the existing owners whose registration date equals the given date. The incoming owner is
572	     * not yet persisted, so it is not included in the count.
573	     *
574	     * @param registrationDate the incoming owner's registration date
575	     * @return the number of existing owners already registered on that date
576	     */
577	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
578	        return (int) this.clinicService.findAllOwners().stream()
579	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
580	            .count();
581	    }
582	
583	    /**
584	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
585	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
586	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
587	     * (postcode is required for the match). When several owners match, the one with the lowest id is
588	     * returned so the result is deterministic; {@code null} when there is no soft match.
589	     *
590	     * @param owner the incoming owner (with normalized telephone and last name resolved)
591	     * @return the lowest-id matching existing owner, or {@code null} when none matches
592	     */
593	    private Owner findPossibleDuplicate(Owner owner) {
594	        if (!StringUtils.hasText(owner.getPostcode())) {
595	            return null;
596	        }
597	        String normalizedLastName = normalizeForComparison(owner.getLastName());
598	        String telephone = owner.getTelephone();
599	        return this.clinicService.findAllOwners().stream()
600	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
601	                && owner.getPostcode().equals(existing.getPostcode())
602	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
603	            .min(java.util.Comparator.comparing(Owner::getId))
604	            .orElse(null);
605	    }
606	
607	    /**
608	     * Generate the deterministic household identifier for the given last name and postcode. The value
609	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
610	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
611	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
612	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
613	     *
614	     * @param lastName the owner's last name
615	     * @param postcode the owner's postcode, may be {@code null}
616	     * @return the deterministic household identifier
617	     */
618	    private String generateHouseholdId(String lastName, String postcode) {
619	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
620	        return shortSha256Hex(key, 12);
621	    }
622	
623	    /**
624	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
625	     * single space, upper-case the result and expand common street-type abbreviations token by token
626	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
627	     * to the empty string. The result is the canonical form that is stored, returned and used for every
628	     * address comparison (household duplicate detection and the shared household id).
629	     *
630	     * @param address the raw address, may be {@code null}
631	     * @return the normalized address
632	     */
633	    private String normalizeAddress(String address) {
634	        if (address == null) {
635	            return "";
636	        }
637	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
638	        if (collapsed.isEmpty()) {
639	            return "";
640	        }
641	        String[] tokens = collapsed.split(" ");
642	        StringBuilder sb = new StringBuilder(collapsed.length());
643	        for (int i = 0; i < tokens.length; i++) {
644	            if (i > 0) {
645	                sb.append(' ');
646	            }
647	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
648	        }
649	        return sb.toString();
650	    }
651	
652	    /**
653	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
654	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
655	     *
656	     * @param value the raw value, may be {@code null}
657	     * @return the normalized value
658	     */
659	    private String normalizeForComparison(String value) {
660	        if (value == null) {
661	            return "";
662	        }
663	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
664	    }
665	
666	    /**
667	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
668	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
669	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
670	     * is returned lower-cased.
671	     *
672	     * @param email the raw email from the request payload, may be {@code null}
673	     * @return the lower-cased email, or {@code null} when none was provided
674	     */
675	    private String normalizeEmail(String email) {
676	        if (!StringUtils.hasText(email)) {
677	            return null;
678	        }
679	        if (!EMAIL_PATTERN.matcher(email).matches()) {
680	            throw new InvalidRequestException(List.of("email"));
681	        }
682	        String lowerCased = email.toLowerCase(Locale.ROOT);
683	        // Reject an address whose domain is on the disposable-domain blocklist.
684	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
685	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
686	            throw new InvalidRequestException(List.of("email"));
687	        }
688	        return lowerCased;
689	    }
690	
691	    /**
692	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
693	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
694	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
695	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
696	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
697	     * to 400 Bad Request).
698	     *
699	     * @param city     the owner's city (used to resolve the region)
700	     * @param postcode the raw postcode from the request payload, may be {@code null}
701	     */
702	    private void validatePostcode(String city, String postcode) {
703	        if (!StringUtils.hasText(postcode)) {
704	            return;
705	        }
706	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
707	            throw new InvalidRequestException(List.of("postcode"));
708	        }
709	        String region = CITY_REGION.get(city);
710	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
711	        if (range != null) {
712	            int value = Integer.parseInt(postcode);
713	            if (value < range[0] || value > range[1]) {
714	                throw new InvalidRequestException(List.of("postcode"));
715	            }
716	        }
717	    }
718	
719	    /**
720	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
721	     * already carries a leading '+' keeps its country code; otherwise the default country code
722	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
723	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
724	     * is thrown (mapped to 400 Bad Request).
725	     *
726	     * @param telephone the raw telephone from the request payload
727	     * @return the E.164 string (e.g. {@code +61412345678})
728	     */
729	    private String normalizeTelephone(String telephone) {
730	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
731	        String candidate;
732	        if (cleaned.startsWith("+")) {
733	            candidate = cleaned;
734	        } else {
735	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
736	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
737	        }
738	        if (!E164_PATTERN.matcher(candidate).matches()) {
739	            throw new InvalidRequestException(List.of("telephone"));
740	        }
741	        // For country codes with a known fixed national-number length, reject a candidate whose
742	        // national digits (everything after the '+' and the country code) do not match that length.
743	        String digits = candidate.substring(1);
744	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
745	            String countryCode = entry.getKey();
746	            if (digits.startsWith(countryCode)) {
747	                int nationalLength = digits.length() - countryCode.length();
748	                if (nationalLength != entry.getValue()) {
749	                    throw new InvalidRequestException(List.of("telephone"));
750	                }
751	                break;
752	            }
753	        }
754	        return candidate;
755	    }
756	
757	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
758	    @Transactional
759	    @Override
760	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
761	        Owner owner = this.clinicService.findOwnerById(ownerId);
762	        if (owner == null) {
763	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
764	        }
765	        // Soft delete: flag the owner deleted and retain the record rather than removing it. The
766	        // owner is still readable afterwards (with 'deleted' true) but is ignored by the create
767	        // endpoint's duplicate/identity checks.
768	        owner.setDeleted(true);
769	        this.clinicService.saveOwner(owner);
770	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
771	    }
772	
773	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
774	    @Override
775	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
776	        Owner owner = this.clinicService.findOwnerById(ownerId);
777	        if (owner == null) {
778	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
779	        }
780	        HttpHeaders headers = new HttpHeaders();
781	        Pet pet = petMapper.toPet(petFieldsDto);
782	        owner.setId(ownerId);
783	        pet.setOwner(owner);
784	        pet.getType().setName(null);
785	        this.clinicService.savePet(pet);
786	        PetDto petDto = petMapper.toPetDto(pet);
787	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
788	            .buildAndExpand(pet.getId()).toUri());
789	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
790	    }
791	
792	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
793	    @Override
794	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
795	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
796	        if (currentOwner != null) {
797	            Pet currentPet = this.clinicService.findPetById(petId);
798	            if (currentPet != null) {
799	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
800	                currentPet.setName(petFieldsDto.getName());
801	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
802	                this.clinicService.savePet(currentPet);
803	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
804	            }
805	        }
806	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
807	    }
808	
809	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
810	    @Override
811	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
812	        HttpHeaders headers = new HttpHeaders();
813	        Visit visit = visitMapper.toVisit(visitFieldsDto);
814	        Pet pet = new Pet();
815	        pet.setId(petId);
816	        visit.setPet(pet);
817	        this.clinicService.saveVisit(visit);
818	        VisitDto visitDto = visitMapper.toVisitDto(visit);
819	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
820	            .buildAndExpand(visit.getId()).toUri());
821	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
822	    }
823	
824	
825	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
826	    @Override
827	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
828	        Owner owner = this.clinicService.findOwnerById(ownerId);
829	        if (owner != null) {
830	            Pet pet = owner.getPet(petId);
831	            if (pet != null) {
832	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
833	            }
834	        }
835	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
836	    }
837	}
